declarations.description:
Run JavaScript that calls other tools. The input is raw JavaScript (not JSON, no code fence), run as an async function body in a QuickJS sandbox: top-level `await` and `return` work. No Node, file system, network, or timers.
- `await tools.<name>({ ...args })` resolves to a string, or an object if the tool's declaration says so, and rejects with an Error on failure. A tool whose declaration returns an object resolves on failure too when it returned that object; check its fields. Calls still running when the script ends are cancelled.
- Optional first line: `// @options: {"max_output_tokens": 10000, "timeout_ms": 60000}`

Globals:
- `text(value)`, `image(dataUrlOrImageBlock)`, `console.log(...)`, and top-level `return` add output; `exit()` ends the script. With several text items, each starts with a `==> text N/M <==` line, and `console` lines follow the other output in one `<console_output>` block. `image()` also saves the image to a temp file and the result names its path.
- `store(key, value)` and `load(key)` keep JSON values across codemode calls.
- `ALL_TOOLS`, `await searchTools(query, { limit?, namespace? })`, `await describeTool(name)`, `await describeNamespace(name)`: find unlisted tools, such as MCP tools.

Nested tools:

### `intelli_fetch`
Fetch one web page with the bounded research page client. Returns page content for extraction, source identity and fetch outcome. It makes no model call.

codemode tool declaration:
```ts
declare const tools: { intelli_fetch(args: {
  // Maximum returned page characters
  // @integer @minimum 1
  maxChars?: number;
  // Page URL
  url: string;
}): Promise<{
  accounting: {
    // @integer @minimum 0 @maximum 9007199254740991
    attempts: number;
    costComplete: boolean;
    estimatedCost: {
      // @minimum 0
      cacheRead?: number;
      // @minimum 0
      cacheWrite?: number;
      // @minimum 0
      input?: number;
      // @minimum 0
      output?: number;
      // @minimum 0
      total?: number;
    };
    // @integer @minimum 0 @maximum 9007199254740991
    missingAttempts: number;
    // @uniqueItems
    missingTokenFields: Array<"inputTotal" | "inputUncached" | "outputTotal" | "cacheRead" | "cacheWrite" | "cacheWrite1h" | "reasoning" | "totalTokens">;
    // @integer @minimum 0 @maximum 9007199254740991
    observedAttempts: number;
    parentDelivery: "available" | "unavailable-after-parent-cancel" | "unknown";
    reportedCost: {
      // @minimum 0
      cacheRead?: number;
      // @minimum 0
      cacheWrite?: number;
      // @minimum 0
      input?: number;
      // @minimum 0
      output?: number;
      // @minimum 0
      total?: number;
    };
    tokens: {
      // @minimum 0
      cacheRead?: number;
      // @minimum 0
      cacheWrite?: number;
      // @minimum 0
      cacheWrite1h?: number;
      // @minimum 0
      inputTotal?: number;
      // @minimum 0
      inputUncached?: number;
      // @minimum 0
      outputTotal?: number;
      // @minimum 0
      reasoning?: number;
      // @minimum 0
      totalTokens?: number;
    };
  };
  attempts: Array<{
    // @integer @minimum 1 @maximum 9007199254740991
    attempt: number;
    // @minLength 1 @maxLength 128 @pattern ^[^\u0000-\u001f\u007f-\u009f\u2028\u2029]+$
    callId: string;
    model: { model: string; provider: string; };
    observation?: { cost?: {
      // @minimum 0
      cacheRead?: number;
      // @minimum 0
      cacheWrite?: number;
      // @minimum 0
      input?: number;
      // @minimum 0
      output?: number;
      // @minimum 0
      total?: number;
    }; costBasis: "reported" | "catalogue" | "unknown"; providerRequestId?: string; source: "provider-response" | "sdk-normalized"; tokens: {
      // @minimum 0
      cacheRead?: number;
      // @minimum 0
      cacheWrite?: number;
      // @minimum 0
      cacheWrite1h?: number;
      // @minimum 0
      inputTotal?: number;
      // @minimum 0
      inputUncached?: number;
      // @minimum 0
      outputTotal?: number;
      // @minimum 0
      reasoning?: number;
      // @minimum 0
      totalTokens?: number;
    }; };
    // @minLength 1 @maxLength 128 @pattern ^[^\u0000-\u001f\u007f-\u009f\u2028\u2029]+$
    operationId: string;
    // @minLength 1 @maxLength 128 @pattern ^[^\u0000-\u001f\u007f-\u009f\u2028\u2029]+$
    pageId?: string;
    // @minimum 0
    queueMs: number;
    role: "search" | "extract" | "collate" | "suggest";
    settledAtMs: number;
    startedAtMs: number;
    state: "succeeded" | "failed" | "aborted" | "timed-out";
  }>;
  cache: { status: "not-requested"; } | { diagnostic: { code: string; message: string; }; status: "unavailable"; } | { accountingPath?: string; diagnostic?: { code: string; message: string; }; index: "updated" | "unavailable"; reportPath: string; runId: string; status: "committed"; };
  counts: {
    // @integer @minimum 0 @maximum 9007199254740991
    cancelled: number;
    // @integer @minimum 0 @maximum 9007199254740991
    candidates: number;
    // @integer @minimum 0 @maximum 9007199254740991
    effectivePageConcurrency: number;
    // @integer @minimum 0 @maximum 9007199254740991
    extracted: number;
    // @integer @minimum 0 @maximum 9007199254740991
    failed: number;
    // @integer @minimum 0 @maximum 9007199254740991
    fetched: number;
    // @integer @minimum 0 @maximum 9007199254740991
    late: number;
    // @integer @minimum 0 @maximum 9007199254740991
    used: number;
  };
  deadline: { enabled: boolean; minimumMet: boolean; reason: "disabled" | "all-terminal" | "adaptive" | "minimum" | "ceiling" | "not-applicable"; };
  details: { [key: string]: unknown; };
  operation: "intelli_fetch";
  // @minLength 1 @maxLength 128
  operationId: string;
  outcome: "completed" | "no-links" | "fetch-failed" | "extraction-failed" | "error" | "aborted";
  related: Array<{ namespace: "v1" | "legacy"; query: string; relevance: string; reportPath: string; }>;
  schemaVersion: 1;
  sources: Array<{
    // @maxLength 500000
    content?: string;
    diagnostic?: string;
    id: string;
    sourceType?: string;
    state: "fetched" | "empty" | "fetch-failed" | "cancelled";
    title: string;
    truncated?: boolean;
    url: string;
  }>;
  summary: string;
  text: string;
  timing: {
    // @minimum 0
    abortToSettledMs?: number;
    // @minimum 0
    allWorkSettledMs: number;
    // @minimum 0
    cutoffMs?: number;
    // @minimum 0
    elapsedMs: number;
    startedUtc: string;
    // @minimum 0
    summaryReadyMs?: number;
  };
}>; };
```
